        WHERE [Sku] = N'BA-S25';
    END

    PRINT N'====================================================================';
    PRINT N'>>> [5] Đang tính toán và đồng bộ lại ProductCount cho Categories...';
    PRINT N'====================================================================';

    UPDATE c
    SET c.[ProductCount] = (SELECT COUNT(1) FROM [dbo].[products] p WHERE p.[CategoryId] = c.[Id])
    FROM [dbo].[categories] c;

    PRINT N'====================================================================';
    PRINT N'>>> [6] Đang khởi tạo Cấu Hình Cửa Hàng & Tài Khoản Quản Trị...';
    PRINT N'====================================================================';

    -- 6. Cấu hình cửa hàng (store_settings)
    IF NOT EXISTS (SELECT 1 FROM [dbo].[store_settings])
    BEGIN
        INSERT INTO [dbo].[store_settings] (
            [Id], [StoreName], [Hotline], [Email], [Address],
            [BankName], [BankAccountName], [BankAccountNumber], [UpdatedAt]
        ) VALUES (
            '88888888-8888-8888-8888-888888888888',
            N'CÔNG TY CỔ PHẦN NỘI THẤT CAO CẤP D2 LUXURY',
            N'0987654321',
            N'contact@d2luxury.vn',
            N'Hà Nội, Việt Nam',
            N'MB Bank',
            N'bùi văn dũng',
            N'00867612199999',
            GETUTCDATE()
        );
    END

    -- 7. Tài khoản quản trị Admin (Mật khẩu: Admin@123)
    IF NOT EXISTS (SELECT 1 FROM [dbo].[users] WHERE [Username] = 'admin')
    BEGIN
        INSERT INTO [dbo].[users] (
            [Id], [Username], [Email], [PasswordHash], [FullName], [Role], [IsActive], [CreatedAt]
        ) VALUES (
            'A1111111-1111-1111-1111-111111111111',
            'admin',
            'admin@d2luxury.vn',
            '$2a$11$Srk96R5aA/m2wkjHj8xsyej6g/nPyAtwE6mnGEPG0//0Gsjf2R9fO',
            N'Quản Trị Viên D2 LUXURY',
            'Admin',
            1,
            GETUTCDATE()
        );
    END

    COMMIT TRANSACTION;
    PRINT N'====================================================================';
    PRINT N'>>> [THÀNH CÔNG] TOÀN BỘ CƠ SỞ DỮ LIỆU ĐÃ ĐƯỢC ĐỒNG BỘ VÀ DEPLOY XONG!';
    PRINT N'====================================================================';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@Err, 16, 1);
END CATCH;
GO

-- Kiểm tra lại tổng quan số lượng dữ liệu sau khi chạy
SELECT 'spaces' AS [Bang], COUNT(1) AS [SoLuongBanGhi] FROM [dbo].[spaces] WHERE [IsDeleted] = 0
UNION ALL
SELECT 'categories' AS [Bang], COUNT(1) AS [SoLuongBanGhi] FROM [dbo].[categories]
UNION ALL
SELECT 'products' AS [Bang], COUNT(1) AS [SoLuongBanGhi] FROM [dbo].[products]
UNION ALL
SELECT 'users' AS [Bang], COUNT(1) AS [SoLuongBanGhi] FROM [dbo].[users]
UNION ALL
SELECT 'store_settings' AS [Bang], COUNT(1) AS [SoLuongBanGhi] FROM [dbo].[store_settings];
GO
